import {nextCardId,normalizeCardIds} from './card-ids.js?v=card-ids-1';
import {FRAME_PRESETS,framePreset,normalizeFrameSettings,cardFrame,photoStyle} from './frames.js?v=photo-1';
import {isPages,providePreview} from './hosting.js';
import {DEFAULT_APPEARANCE,DISPLAY_FONTS,loadAppearance,applyLoginAppearance} from './appearance.js';
import {loadLegacyGallery,mergeGallery,mediaType,safeMediaUrl} from './gallery.js';
const $=id=>document.getElementById(id),clone=v=>structuredClone(v);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let draft,revision=0,draftVersion=0,csrf='',dirty=false,busy=false,view='overview',legacy=[],legacyLoading=true,legacyError='',undo=[],redo=[],modalDraft=null,selectedCollection=null,cardQuery='',cardCol='all',cardRarity='all',galleryQuery='',galleryFilter='all',selectedMedia=new Set(),updatedAt=null;
const loginPreview=new URLSearchParams(location.search).has('login-preview');
let staleDraft=false,publishedDocument=null,syncNotice='',recoveryAvailable=false,syncing=false,lastSync=0;
let loginAppearance=structuredClone(DEFAULT_APPEARANCE.login);
function ensureFrameSettings(doc){if(doc?.config){normalizeFrameSettings(doc.config);normalizeCardIds(doc.config);}return doc;}
function frameClass(src){const preset=framePreset(src);return preset?' frame-preset frame-preset-'+preset:'';}
function frameField(path,label,hint){
 const value=get(path);
 return `<div class="frame-field" data-frame-field="${esc(path)}"><div class="frame-presets" aria-label="Готовые рамки: ${esc(label)}">${Object.entries(FRAME_PRESETS).map(([id,p])=>`<button type="button" data-action="choose-frame" data-path="${esc(path)}" data-preset="${id}" aria-pressed="${value===p.src}"><span class="frame-swatch"><img src="${p.src}" class="frame-preset frame-preset-${id}" alt=""></span><span>${esc(p.label)}</span></button>`).join('')}</div>${art(path,label,hint)}</div>`;
}
function cardPreviewHtml(card){
 const src=cardFrame(card,draft.config.theme),preset=framePreset(src);
 return `<span class="card-face${src?' has-frame':''}${preset?' has-builtin-frame':''}" style="--frame-inset:${draft.config.theme.frameInset}%;${photoStyle(card)}"><span class="card-photo"><img class="card-art" loading="lazy" decoding="async" src="${esc(imageUrl(card.img))}" alt="${esc(card.name)}"></span>${src?`<img class="card-frame${frameClass(src)}" src="${esc(imageUrl(src))}" alt="">`:''}</span>`;
}
function cardPreviewSignature(card){return JSON.stringify([card.img,card.frame,card.frameEnabled,card.r,card.name,draft.config.theme.frames,draft.config.theme.frameInset]);}
function photoControls(){
 return `<section class="photo-editor"><div id="card-frame-preview" class="card-live-preview" data-signature="${esc(cardPreviewSignature(modalDraft))}">${cardPreviewHtml(modalDraft)}</div><div class="photo-controls"><h3>Положение фото</h3><p class="hint">Настройте фото внутри карты. Рамка остаётся на месте.</p>${[['zoom','Масштаб (×)',1,4,.01],['x','X · влево / вправо, %',-100,100,1],['y','Y · вверх / вниз, %',-100,100,1]].map(([key,label,min,max,step])=>`<label class="photo-control">${label}<span><input type="range" data-bind="@.photo.${key}" aria-label="${label} — ползунок" min="${min}" max="${max}" step="${step}" value="${modalDraft.photo[key]}"><input type="number" data-bind="@.photo.${key}" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${modalDraft.photo[key]}"></span></label>`).join('')}<button type="button" class="secondary" data-action="reset-photo">Сбросить положение фото</button></div></section>`;
}
function refreshFramePreviews(){
 if(modalDraft?.photo)document.querySelectorAll('[data-bind^="@.photo."]').forEach(input=>{if(input!==document.activeElement)input.value=get(input.dataset.bind);});
 document.querySelectorAll('.art-field').forEach(el=>{const input=el.querySelector('input[data-bind]');if(!input)return;const img=el.querySelector('img'),url=imageUrl(get(input.dataset.bind));if(url){if(img.getAttribute('src')!==url)img.src=url;}else if(img.hasAttribute('src'))img.removeAttribute('src');});
 document.querySelectorAll('[data-frame-field]').forEach(el=>{const value=get(el.dataset.frameField);el.querySelector('.art-field>img').className=frameClass(value).trim();el.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',String(FRAME_PRESETS[b.dataset.preset].src===value)));});
 const preview=$('card-frame-preview');if(!modalDraft||!preview)return;
 const signature=cardPreviewSignature(modalDraft);
 if(preview.dataset.signature!==signature){preview.innerHTML=cardPreviewHtml(modalDraft);preview.dataset.signature=signature;}
 else preview.querySelector('.card-face').style.cssText=`--frame-inset:${draft.config.theme.frameInset}%;${photoStyle(modalDraft)}`;
}
let previewRefresh=0;
function scheduleFramePreviews(){if(!previewRefresh)previewRefresh=requestAnimationFrame(()=>{previewRefresh=0;refreshFramePreviews();});}

const titles={balance:'Локальный баланс',website:'Оформление сайта',login:'Экран входа',overview:'Обзор',gallery:'Архив',collections:'Коллекции',cards:'Карты',rules:'Правила и награды',theme:'Оформление гачи',texts:'Тексты и справка',backup:'Копии и история',security:'Доступ'};
const descriptions={balance:'Измените текущий баланс игры в этом браузере. Применяется сразу, без публикации; баланс других игроков не меняется.',website:'Название, тексты, палитра и макет главной страницы.',login:'Тексты, логотип, изображения и оформление экрана входа в студию.',overview:'Создавайте коллекции, настраивайте игру и наполняйте архив.',gallery:'Фото, анимация и видео. Изменения появятся на сайте после публикации.',collections:'Соберите карты в коллекции и задайте для каждой собственные правила.',cards:'Создавайте карты, выбирайте редкость и управляйте шансом каждой карты.',rules:'Экономика, гарантированные призы и мини-игры.',theme:'Цвета, изображения, шрифты и эффекты вашей игры.',texts:'Названия кнопок и справка для игроков.',backup:'Сохраняйте копии и возвращайтесь к предыдущим публикациям.',security:'Смените пароль и управляйте доступом к студии.'};
function notify(message,error=false){const el=$('notification');el.textContent=message;el.className='notification'+(error?' error':'');el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,error?10000:4500);}
async function api(path,{method='GET',data,raw}={}){if(isPages()){const {pagesApi}=await import('./pages-admin.js?v=draft-sync-1');try{return await pagesApi(path,{method,data,raw});}catch(error){if(error.status===401&&path!=='api/login'&&!dirty)showLogin();throw error;}}const headers={};if(method!=='GET')headers['X-CSRF-Token']=csrf;if(data!==undefined)headers['Content-Type']='application/json';if(raw)headers['Content-Type']=raw.type||'application/octet-stream';const res=await fetch(path,{method,headers,body:raw|| (data!==undefined?JSON.stringify(data):undefined),cache:'no-store'});let body;try{body=await res.json();}catch{throw new Error('Сервер недоступен. Запустите npm start и откройте сайт по HTTP.');}if(!res.ok){if(res.status===401&&path!=='api/login'){if(dirty)notify('Сеанс завершён. Экспортируйте копию перед повторным входом.',true);else showLogin();}throw Object.assign(new Error(body.error||'Не удалось выполнить запрос.'),{status:res.status});}return body;}
function get(path){return path.split('.').reduce((value,key)=>value?.[key],path.startsWith('@.')?{ '@':modalDraft}:draft);}
function set(path,value){const keys=path.split('.'),last=keys.pop();let obj=path.startsWith('@.')?{'@':modalDraft}:draft;for(const key of keys){if(['__proto__','constructor','prototype'].includes(key))throw new Error('Недопустимое поле.');obj=obj[key];}obj[last]=value;}
function commit(fn,refresh=true){undo.push(clone(draft));if(undo.length>35)undo.shift();redo=[];fn();ensureFrameSettings(draft);if(draft.appearance===undefined)draft.appearance=clone(DEFAULT_APPEARANCE);dirty=true;if(refresh)render();else status();}
function status(){$('content').inert=busy;const el=$('save-status');el.textContent=busy?(syncing?'Синхронизация…':'Сохранение…'):dirty?'Есть несохранённые изменения':`Черновик сохранён · публикация №${revision}`;el.classList.toggle('dirty',dirty);$('undo').disabled=busy||!undo.length;$('redo').disabled=busy||!redo.length;for(const id of ['save-draft','publish','preview','logout'])$(id).disabled=busy;}
function showLogin(){$('studio').hidden=true;$('login-screen').hidden=false;$('password').value='';applyLoginAppearance(loginAppearance);configurePasswordLogin();}
async function load(){const s=await api('api/admin/state');draft=ensureFrameSettings(clone(s.draft));revision=s.revision;draftVersion=s.draftVersion;csrf=s.csrf;updatedAt=s.updatedAt;staleDraft=!!s.stale;publishedDocument=s.basePublished?clone(s.basePublished):null;syncNotice=s.syncNotice||'';recoveryAvailable=!!s.recoveryAvailable;dirty=false;undo=[];redo=[];$('login-screen').hidden=true;$('studio').hidden=false;render();if(legacyLoading)loadLegacy();}
async function syncStudio(){
 if(!isPages()||!draft||$('studio').hidden||dirty||busy||syncing||$('modal').open||Date.now()-lastSync<3000)return;
 syncing=true;busy=true;lastSync=Date.now();status();
 try{const result=await api('api/admin/sync',{method:'POST'});if(result.changed)await load();}catch(error){if(error.status!==401)notify(error.message,true);}finally{syncing=false;busy=false;status();}
}
function publishedMissingCards(){
 const missing=(publishedDocument?.config.cards||[]).filter(card=>!draft.config.cards.some(item=>item.id===card.id));
 if(!missing.length)return '';
 return panel('Карты на сайте, отсутствующие в черновике',`<p class="hint">Эти карты сейчас доступны в гаче. Они удалены только из черновика; верните их, чтобы редактировать здесь.</p><div class="media-grid">${missing.map(card=>`<article class="media-card card-art">${cardPreviewHtml(card)}<div class="media-meta"><h3>${esc(card.name)}</h3><p>ID ${card.id} · ${card.r} · Опубликована</p><button data-action="restore-published-card" data-id="${card.id}">Вернуть в черновик</button></div></article>`).join('')}</div>`);
}

async function loadLegacy(){try{legacy=await loadLegacyGallery();legacyError='';}catch(e){legacyError=e.message;notify('Сохранённый архив не загрузился. Повторите загрузку позже.',true);}finally{legacyLoading=false;if(['gallery','overview'].includes(view))render();}}
const imageUrl=url=>/^data:image\/(png|jpeg|webp|gif|avif);base64,/.test(url||'')?url:safeMediaUrl(url);
const options=(values,value)=>values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(label)}</option>`;}).join('');
function field(path,label,{type='text',hint='',min,max,step,values,wide=false,rows=3}={}){const value=get(path);let input;const common=`data-bind="${esc(path)}"`;if(type==='checkbox')return `<label class="toggle${wide?' wide':''}"><input ${common} type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;if(type==='select')input=`<select ${common}>${options(values,value)}</select>`;else if(type==='textarea')input=`<textarea ${common} rows="${rows}">${esc(value)}</textarea>`;else if(type==='json')input=`<textarea ${common} data-format="json" rows="${rows}" spellcheck="false">${esc(JSON.stringify(value,null,2))}</textarea>`;else if(type==='list')input=`<input ${common} data-format="list" value="${esc(value.join(', '))}">`;else input=`<input ${common} type="${type}" value="${esc(value)}"${min!==undefined?` min="${min}"`:''}${max!==undefined?` max="${max}"`:''}${step!==undefined?` step="${step}"`:''}>`;return `<label class="${wide?'wide':''}">${esc(label)}${input}${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
const number=(path,label,hint='',max=1000000,step=1,min=0)=>field(path,label,{type:'number',min,max,step,hint});
function art(path,label,hint='HTTPS-ссылка или файл с компьютера.'){const value=get(path),url=imageUrl(value),isFrame=path.endsWith('.frame')||path.includes('.frames.');return `<div class="art-field"><img class="${isFrame?frameClass(value):''}" ${url?`src="${esc(url)}"`:''} alt="Предпросмотр: ${esc(label)}"><div>${field(path,label,{hint})}<label>Загрузить изображение<input type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/avif" data-upload-path="${esc(path)}"></label><button data-action="clear-art" data-path="${esc(path)}" class="secondary">Очистить изображение</button></div></div>`;}
function panel(title,body,extra=''){return `<section class="panel"><div class="panel-title"><h2>${esc(title)}</h2>${extra}</div>${body}</section>`;}
function settingFields(prefix){return `<div class="fields three">${number(prefix+'.price','Цена крутки, 💎')}${number(prefix+'.sr','SR, %','',100,.1)}${number(prefix+'.r','R, %','',100,.1)}${number(prefix+'.money','Денежный приз, %','Остаток шанса — карты N.',100,.1)}${number(prefix+'.pityR','Гарант R+','0 — выключить.')}${number(prefix+'.pityS','Гарант SR','0 — выключить.')}${number(prefix+'.bannerRate','Шанс баннерной SR, %','',100,.1)}${field(prefix+'.bannerGuarantee','Гарант баннера после проигрыша',{type:'checkbox'})}</div><p class="remainder" data-remainder="${esc(prefix)}">Шанс N: ${(100-get(prefix+'.sr')-get(prefix+'.r')-get(prefix+'.money')).toFixed(1)}%</p>`;}
function galleryItems(){return mergeGallery(legacy,draft.gallery);}
function render(){if(!draft)return;document.querySelectorAll('#navigation [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});$('breadcrumb').textContent=titles[view].toUpperCase();$('content').innerHTML=`<div class="page-heading"><div><p class="section-kicker">ЮМИЛИЯ STUDIO</p><h1>${titles[view]}</h1><p>${descriptions[view]}</p></div></div>`+(staleDraft?'<div class="notice">На сайте есть более новая версия. Экспортируйте черновик в разделе «Копии и история», затем загрузите опубликованную версию.</div>':'')+(syncNotice?`<div class="notice" role="status">${esc(syncNotice)}${recoveryAvailable?' <button data-action="download-recovery">Скачать прежний черновик</button>':''}</div>`:'')+views[view]();status();}
function localPlayer(){const raw=localStorage.getItem('gacha3');const player=raw?JSON.parse(raw):{};if(!player||typeof player!=='object'||Array.isArray(player))throw new Error('Не удалось прочитать прогресс игры.');return player;}
const views={
 balance(){try{const gems=localPlayer().gems??draft.config.economy.startingGems;return panel('Текущий баланс, 💎',`<div class="fields"><label>Новый баланс<input id="local-balance" type="number" min="0" max="9007199254740991" step="1" value="${esc(gems)}"></label></div><div class="actions" style="margin-top:20px"><button class="primary" data-action="save-local-balance">Применить баланс</button><button data-action="refresh-local-balance">Обновить значение</button></div><p class="hint">Сохраняется только на этом устройстве и в этом браузере. Открытая игра обновится автоматически. Карты, крутки и остальной прогресс сохраняются.</p>`);}catch{return panel('Баланс недоступен','<p class="error">Не удалось прочитать локальный прогресс. Откройте игру в этом же браузере и повторите попытку.</p>');}},
 overview(){const c=draft.config;return `<div class="stats"><div class="stat"><strong>${galleryItems().length}${legacyLoading?'…':''}</strong><span>файлов в архиве</span></div><div class="stat"><strong>${c.cols.length}</strong><span>коллекций</span></div><div class="stat"><strong>${c.cards.length}</strong><span>карточек</span></div><div class="stat"><strong>${revision}</strong><span>опубликованная версия</span></div></div><section class="panel welcome"><p class="eyebrow">ПРОСТРАНСТВО ДЛЯ НОВОЙ ИСТОРИИ</p><h2>Всё начинается с коллекции.</h2><p>Добавьте карты, настройте награды и посмотрите результат. Сайт обновится, когда вы нажмёте «Опубликовать».</p><button class="primary" data-go="cards">Управлять картами →</button><button data-go="gallery">Добавить в архив</button></section><div class="split">${panel('Состояние игры',`<ul class="checklist"><li>Название <strong>${esc(c.title)}</strong></li><li>Активные коллекции <span>${c.cols.filter(x=>x.enabled).length} / ${c.cols.length}</span></li><li>Рулетка осколков <span>${c.mini.enabled?'Включена':'Выключена'}</span></li><li>Мини-игра 2048 <span>${c.game2048.enabled?'Включена':'Выключена'}</span></li><li>Последняя публикация <span>${updatedAt?new Date(updatedAt).toLocaleString('ru-RU'):'Ещё не было'}</span></li></ul>`)}${panel('Как устроена студия','<ol><li>Измените архив и игру в нужном разделе.</li><li>Сохраните черновик — он доступен только вам.</li><li>Проверьте игру в предпросмотре.</li><li>Опубликуйте готовую версию.</li></ol><p class="hint">Предпросмотр использует отдельное сохранение. Прогресс игроков остаётся прежним.</p>')}</div>`;},
 gallery(){const all=galleryItems(),items=all.filter(x=>(galleryFilter==='all'||mediaType(x)===galleryFilter)&&`${x.name||''} ${x.url}`.toLowerCase().includes(galleryQuery.toLowerCase()));return `<div class="drop-zone" id="gallery-drop"><h3>Добавьте что-то особенное</h3><p class="muted">Перетащите фото, GIF или видео. До 40 МБ на файл.</p><input id="gallery-upload" type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,image/avif,video/mp4,video/webm,video/quicktime,video/ogg"><div class="file-progress" id="upload-progress" role="status"></div></div>${legacyLoading?'<p class="notice">Загружаем существующий архив…</p>':''}${legacyError?`<div class="notice">${esc(legacyError)} <button data-action="reload-gallery">Повторить</button></div>`:''}<div class="search-bar"><input id="gallery-search" aria-label="Поиск в архиве" placeholder="Поиск по имени…" value="${esc(galleryQuery)}"><div class="filters">${[['all','Все'],['image','Фото'],['gif','GIF'],['video','Видео']].map(([id,label])=>`<button data-gallery-filter="${id}" class="${galleryFilter===id?'active':''}">${label} <span class="chip">${all.filter(x=>id==='all'||mediaType(x)===id).length}</span></button>`).join('')}</div></div><div class="pending-bar"><span>Выбрано: ${selectedMedia.size} · Найдено: ${items.length}</span><div class="actions"><button data-action="select-all">Выбрать показанные</button><button data-action="clear-selection">Снять выбор</button><button class="danger" data-action="remove-selected" ${selectedMedia.size?'':'disabled'}>Убрать из архива</button></div></div><div class="media-grid">${items.map(x=>{const url=safeMediaUrl(x.url);if(!url)return '';return `<article class="media-card"><label class="media-check"><input aria-label="Выбрать ${esc(x.name||'файл')}" type="checkbox" data-media-select="${esc(x.url)}" ${selectedMedia.has(x.url)?'checked':''}></label>${mediaType(x)==='video'?`<video src="${esc(url)}" controls preload="none" playsinline></video>`:`<img src="${esc(url)}" alt="${esc(x.name||'') }" loading="lazy" decoding="async">`}<div class="media-meta"><h3 title="${esc(x.name)}">${esc(x.name||'Без названия')}</h3><p>${mediaType(x).toUpperCase()}</p><div class="actions"><button data-action="rename-media" data-url="${esc(x.url)}">Название</button><button data-action="move-media" data-url="${esc(x.url)}">↑ В начало</button></div></div></article>`;}).join('')}</div>${!items.length?'<div class="empty">Файлов пока нет или ничего не найдено.</div>':''}<p class="hint">Удаление из архива скрывает файл на сайте. Оригиналы Cloudinary и загруженные файлы сохраняются для восстановления.</p>`;},
 collections(){const c=draft.config;let html=`<div class="actions" style="margin-bottom:20px"><button class="primary" data-action="add-collection">+ Создать коллекцию</button></div>`;html+=c.cols.map((col,i)=>`<section class="panel collection-row">${col.cover?`<img src="${esc(imageUrl(col.cover))}" alt="">`:''}<div class="details"><h3>${esc(col.name)} <span class="badge ${col.enabled?'green':''}">${col.enabled?'Активна':'Скрыта'}</span></h3><p>${esc(col.id)} · ${c.cards.filter(x=>x.col===col.id).length} карт · ${col.settings.price} 💎 / крутка</p></div><div class="actions"><button data-action="edit-collection" data-index="${i}">Настроить</button><button data-action="duplicate-collection" data-index="${i}">Копия</button><button data-action="up-collection" data-index="${i}" ${i?'':'disabled'} aria-label="Поднять коллекцию">↑</button><button data-action="down-collection" data-index="${i}" ${i<c.cols.length-1?'':'disabled'} aria-label="Опустить коллекцию">↓</button><button class="danger" data-action="remove-collection" data-index="${i}">Удалить</button></div></section>`).join('');if(selectedCollection!==null&&c.cols[selectedCollection]){const i=selectedCollection,p=`config.cols.${i}`,col=c.cols[i];html+=panel(`Настройки: ${col.name}`,`<div class="fields">${field(p+'.name','Название')}${field(p+'.id','Постоянный ID',{hint:'При изменении карты будут перенесены автоматически.'})}${field(p+'.desc','Описание',{type:'textarea',wide:true})}${field(p+'.enabled','Показывать коллекцию в игре',{type:'checkbox',wide:true})}</div><div style="margin:22px 0">${art(p+'.cover','Обложка коллекции')}</div><h3>Шансы и гаранты</h3>${settingFields(p+'.settings')}<div class="fields">${field(p+'.settings.banner','Закреплённая баннерная SR',{type:'select',values:[[0,'Игрок выбирает баннер'],...c.cards.filter(x=>x.col===col.id&&x.r==='SR'&&x.enabled).map(x=>[x.id,x.name])]})}</div><p class="hint">Цена, шансы и гаранты этой коллекции имеют приоритет над базовыми правилами.</p>`);}return html||'<div class="empty">Создайте первую коллекцию.</div>';},
 cards(){const c=draft.config,cards=c.cards.filter(x=>(cardCol==='all'||x.col===cardCol)&&(cardRarity==='all'||x.r===cardRarity)&&`${x.name} ${x.id}`.toLowerCase().includes(cardQuery.toLowerCase()));return publishedMissingCards()+`<div class="search-bar"><input id="card-search" aria-label="Поиск карт" placeholder="Найти карту…" value="${esc(cardQuery)}"><select id="card-col" aria-label="Коллекция">${options([['all','Все коллекции'],...c.cols.map(x=>[x.id,x.name])],cardCol)}</select><select id="card-rarity" aria-label="Редкость">${options([['all','Любая редкость'],'N','R','SR'],cardRarity)}</select><button class="primary" data-action="add-card">+ Новая карта</button></div><div class="media-grid">${cards.map(x=>`<article class="media-card card-art">${cardPreviewHtml(x)}<div class="media-meta"><h3>${esc(x.name)}</h3><p><span class="badge ${x.r==='SR'?'gold':''}">${x.r}</span> · ${esc(c.cols.find(y=>y.id===x.col)?.name)} · ID ${x.id}${x.enabled?'':' · Скрыта'}</p><div class="actions"><button data-action="edit-card" data-id="${x.id}">Изменить</button><button data-action="duplicate-card" data-id="${x.id}">Копия</button><button class="danger" data-action="remove-card" data-id="${x.id}">Удалить</button></div></div></article>`).join('')}</div>${!cards.length?'<div class="empty">Карт с такими параметрами нет.</div>':''}<p class="hint">Вес карты влияет на её шанс внутри одной редкости. Все веса 1 — равные шансы. ID карты хранит прогресс игроков и не меняется при редактировании.</p>`;},
 rules(){return panel('Базовые правила',`${settingFields('config.defaults')}<button data-action="apply-defaults">Применить базовые правила ко всем коллекциям</button><p class="hint">Новые коллекции используют эти значения. Для существующих коллекций правила настраиваются отдельно.</p>`)+panel('Экономика',`<div class="fields three">${number('config.economy.startingGems','Стартовый баланс, 💎','Только для новых игроков.')}${number('config.economy.startingFree','Стартовые бесплатные крутки','Только для новых игроков.')}${number('config.economy.dailyFree','Ежедневные бесплатные крутки')}${field('config.economy.moneyPrizes','Денежные призы за крутку',{type:'list',wide:true,hint:'Суммы через запятую; выбираются с равным шансом.'})}</div><h3 style="margin-top:22px">Дубликаты карт</h3><div class="fields three">${['N','R','SR'].map(r=>number('config.economy.shards.'+r,`Осколки за дубль ${r}`)+number('config.economy.sellPrices.'+r,`Продажа дубля ${r}, 💎`)).join('')}</div>`)+panel('Рулетка осколков',`${field('config.mini.enabled','Включить рулетку',{type:'checkbox'})}<div class="fields">${number('config.mini.baseCost','Первая крутка дня, ✦')}${number('config.mini.costStep','Подорожание за крутку, ✦')}${number('config.mini.guaranteeEvery','Гарант через каждые N круток','0 — выключить.')}${number('config.mini.guaranteeMin','Минимальная сумма гаранта, 💎')}</div><h3 style="margin-top:24px">Призы и их вес</h3>${draft.config.mini.prizes.map((p,i)=>`<div class="fields three" style="margin-bottom:12px">${number(`config.mini.prizes.${i}.0`,'Сумма, 💎')}${number(`config.mini.prizes.${i}.1`,'Вес','',1000000,.1,.001)}<button data-action="remove-prize" data-index="${i}" class="danger">Убрать приз</button></div>`).join('')}<button data-action="add-prize">+ Добавить приз</button>`)+panel('Мини-игра 2048',`${field('config.game2048.enabled','Включить 2048',{type:'checkbox'})}<div class="fields">${number('config.game2048.dailyLimit','Дневной лимит наград, 💎')}${field('config.game2048.rewards','Награды за плитки',{type:'json',rows:8,hint:'Слева — число на плитке (степень двойки), справа — награда в 💎. Каждая награда выдаётся один раз за партию.'})}</div>`);},
 theme(){return panel('Основное',`<div class="fields">${field('config.title','Название игры')}${field('config.theme.font','Шрифт',{type:'select',values:['Philosopher','Montserrat','Cormorant Garamond','system-ui']})}${number('config.theme.maxWidth','Максимальная ширина игры, px','',1800,1,400)}${number('config.theme.cardRadius','Скругление карт, px','',40)}</div>`)+panel('Палитра',`<div class="fields three">${Object.entries({bg:'Фон',panel:'Панели',line:'Границы',text:'Основной текст',muted:'Вторичный текст',accent:'Акцент',N:'Обычная карта N',R:'Редкая карта R',SR:'Суперредкая карта SR'}).map(([k,label])=>field('config.theme.'+k,label,{type:'color'})).join('')}</div>`)+panel('Изображения',`<div class="split">${art('config.theme.background','Фон игры')}${art('config.back','Рубашка карт')}${art('config.theme.pill','Панели баланса')}${art('config.theme.button','Кнопка крутки')}</div><p class="hint">Прозрачные PNG и WEBP подходят для кнопок и панелей. Пустое изображение заменяется цветом панели.</p>`)+panel('Рамки карт',`<p class="hint">Накладываются поверх изображения карты. Используйте PNG или WEBP с прозрачным центром. Готовые серебряная N, синяя R и золотая SR уже загружены из исходных карт. Новые изображения получают рамку своей редкости; исходные карты сохраняют встроенную рамку.</p><div class="split">${['N','R','SR'].map(r=>frameField('config.theme.frames.'+r,'Рамка '+r,'Пусто — использовать изображение карты без дополнительной рамки.')).join('')}</div><div class="fields" style="margin-top:20px">${number('config.theme.frameInset','Отступ изображения внутри рамки, %','Применяется только к картам с отдельной рамкой. Результат виден в предпросмотре игры.',30,.5)}</div>`)+panel('Анимация и звук',`<div class="fields three">${field('config.effects.sound','Звук',{type:'checkbox'})}${field('config.effects.flash','Вспышки при редких призах',{type:'checkbox'})}${field('config.effects.vibration','Вибрация',{type:'checkbox'})}${number('config.effects.volume','Громкость (0–1)','',1,.05)}${number('config.effects.spinSeconds','Длительность крутки, сек.','',30,.1,.2)}${number('config.effects.multiSpinSeconds','Крутка в серии, сек.','',30,.1,.2)}</div>`);},
 texts(){return panel('Кнопки и подписи',`<div class="fields">${Object.entries({summon:'Вкладка призыва',collection:'Вкладка коллекции',game2048:'Вкладка 2048',help:'Вкладка справки',pull:'Кнопка крутки',again:'Повторить крутку',close:'Закрыть результат',skip:'Пропустить анимацию',dailyBonus:'Ежедневный бонус',collectionDone:'Коллекция собрана',mini:'Рулетка осколков'}).map(([k,label])=>field('config.labels.'+k,label)).join('')}</div>`)+panel('Справка',`<p class="muted">Тексты поддерживают переменные: {{price}}, {{sr}}, {{r}}, {{money}}, {{pityR}}, {{pityS}}, {{bannerRate}}, {{dailyFree}}, {{startingGems}}, {{dailyLimit}}, {{miniBase}}, {{miniStep}}, {{miniGuarantee}}, {{miniMin}}.</p>${draft.config.help.map((h,i)=>`<div class="help-entry"><div class="fields">${field(`config.help.${i}.title`,'Заголовок',{wide:true})}${field(`config.help.${i}.body`,'Текст',{type:'textarea',rows:5,wide:true})}</div><div class="actions"><button data-action="up-help" data-index="${i}" ${i?'':'disabled'}>↑ Выше</button><button data-action="down-help" data-index="${i}" ${i<draft.config.help.length-1?'':'disabled'}>↓ Ниже</button><button class="danger" data-action="remove-help" data-index="${i}">Удалить раздел</button></div></div>`).join('')}<button data-action="add-help">+ Раздел справки</button>`);},
 website(){const p='appearance.site';return `<div class="actions" style="margin-bottom:22px"><button class="primary" data-action="preview-site">Предпросмотр сайта</button><button data-action="reset-site">Вернуть исходное оформление</button></div>`+panel('Название и навигация',`<div class="fields">${field(p+'.title','Заголовок вкладки браузера')}${field(p+'.name','Название сайта')}${field(p+'.subtitle','Подзаголовок',{wide:true})}${field(p+'.archivesLabel','Кнопка архива')}${field(p+'.gachaLabel','Кнопка гачи')}${field(p+'.adminLabel','Кнопка администратора')}${field(p+'.footer','Текст внизу страницы',{wide:true})}</div>`)+panel('Цвета и фон',`<div class="fields three">${Object.entries({bg:'Основной фон',panel:'Фон карточек',accent:'Акцент и активные кнопки',text:'Основной текст',muted:'Вторичный текст',glow1:'Первое свечение',glow2:'Второе свечение'}).map(([key,label])=>field(p+'.'+key,label,{type:'color'})).join('')}</div><div style="margin-top:22px">${art(p+'.background','Фоновое изображение сайта')}</div>`)+panel('Шрифты и шапка',`<div class="fields">${field(p+'.titleFont','Шрифт названия',{type:'select',values:DISPLAY_FONTS})}${field(p+'.bodyFont','Шрифт текста',{type:'select',values:DISPLAY_FONTS})}${number(p+'.titleSize','Максимальный размер названия, px','На маленьком экране размер уменьшается автоматически.',120,1,32)}${number(p+'.headerPadding','Отступ над названием, px','',120,1,16)}${field(p+'.showSubtitle','Показывать подзаголовок',{type:'checkbox'})}${field(p+'.showDecorations','Показывать декоративные линии',{type:'checkbox'})}${field(p+'.showFilters','Показывать фильтры архива',{type:'checkbox'})}${field(p+'.showFooter','Показывать нижнюю строку',{type:'checkbox'})}</div>`)+panel('Галерея',`<div class="fields">${field(p+'.layout','Макет',{type:'select',values:[['masonry','Колонки с разной высотой'],['grid','Ровная сетка']]})}${field(p+'.aspectRatio','Формат фото и видео',{type:'select',values:[['auto','Оригинальные пропорции'],['1/1','Квадрат 1:1'],['4/5','Портрет 4:5'],['3/4','Портрет 3:4'],['16/9','Широкий 16:9']]})}${number(p+'.columns','Колонки на большом экране','',6,1,1)}${number(p+'.mobileColumns','Колонки на телефоне','До 480 px; на планшетах колонки подбираются автоматически.',2,1,1)}${number(p+'.gap','Промежутки между файлами, px','',40)}${number(p+'.cardRadius','Скругление карточек, px','',40)}${number(p+'.contentWidth','Максимальная ширина архива, px','',2000,1,700)}${field(p+'.hoverZoom','Увеличивать изображение при наведении',{type:'checkbox'})}${field(p+'.autoplayVideos','Автоматически воспроизводить видео без звука',{type:'checkbox'})}</div>`)+panel('Подписи архива',`<div class="fields">${field(p+'.filterAll','Все файлы')}${field(p+'.filterImage','Фотографии')}${field(p+'.filterGif','GIF')}${field(p+'.filterVideo','Видео')}${field(p+'.loadingText','Сообщение загрузки')}${field(p+'.emptyText','Сообщение пустого архива')}${field(p+'.emptyIcon','Символ пустого архива')}${field(p+'.closeLabel','Закрыть просмотр файла')}</div>`);},
 login(){const p='appearance.login';return `<div class="actions" style="margin-bottom:22px"><button class="primary" data-action="preview-login">Предпросмотр экрана входа</button><button data-action="reset-login">Вернуть исходный экран</button></div>`+panel('Бренд и приветствие',`<div class="fields">${field(p+'.pageTitle','Заголовок вкладки входа')}${field(p+'.brand','Название бренда')}${field(p+'.brandTag','Подпись под брендом')}${field(p+'.tagline','Небольшой заголовок над приветствием')}${field(p+'.headline','Приветственный заголовок',{type:'textarea',wide:true,hint:'Переносы строк сохраняются.'})}${field(p+'.description','Описание',{type:'textarea',wide:true})}${field(p+'.backLabel','Ссылка возврата на сайт')}</div>`)+panel('Форма входа',`<div class="fields">${field(p+'.eyebrow','Надпись над формой')}${field(p+'.heading','Заголовок формы')}${field(p+'.intro','Описание формы',{wide:true})}${field(p+'.passwordLabel','Подпись поля пароля')}${field(p+'.submitLabel','Текст кнопки входа')}${field(p+'.sessionNote','Текст под формой',{wide:true})}${field(p+'.invalidPasswordMessage','Сообщение неверного пароля',{wide:true})}</div><p class="hint">Оформление не меняет пароль, срок сеанса или правила входа. Пароль меняется в разделе «Доступ».</p>`)+panel('Макет и шрифты',`<div class="fields">${field(p+'.layout','Расположение',{type:'select',values:[['split','Приветствие слева, форма справа'],['centered','По центру страницы']]})}${field(p+'.showStory','Показывать блок приветствия',{type:'checkbox'})}${field(p+'.titleFont','Шрифт заголовков',{type:'select',values:DISPLAY_FONTS})}${field(p+'.bodyFont','Шрифт текста',{type:'select',values:DISPLAY_FONTS})}${field(p+'.symbol','Декоративный символ',{hint:'Можно использовать цветок, звезду или эмодзи.'})}</div>`)+panel('Цвета',`<div class="fields three">${Object.entries({bg:'Фон страницы',panel:'Панели',accent:'Кнопки и акценты',text:'Основной текст',muted:'Вторичный текст',hero:'Свечение приветствия'}).map(([key,label])=>field(p+'.'+key,label,{type:'color'})).join('')}</div>`)+panel('Изображения',`<div class="split">${art(p+'.logo','Логотип')}${art(p+'.artwork','Иллюстрация вместо символа')}${art(p+'.background','Фон приветствия')}</div>`);},
 backup(){return (recoveryAvailable?panel('Черновик до синхронизации','<p class="muted">Предыдущие правки сохранены отдельно. Скачайте копию для просмотра или восстановления.</p><button data-action="download-recovery">Скачать прежний черновик</button>'):'')+(isPages()?panel('Опубликованная версия','<p class="muted">Загрузить опубликованные настройки вместо черновика этого браузера. Сначала экспортируйте нужные изменения.</p><button data-action="reload-published">Загрузить опубликованную версию</button>'):'')+panel('Резервная копия',`<p class="muted">Экспорт содержит черновик игры и изменения архива. Загруженные файлы хранятся отдельно: сохраняйте папки assets и uploads вместе с сервером.</p><div class="actions"><button class="primary" data-action="export">Скачать JSON</button><label>Импортировать JSON<input type="file" id="import-json" accept="application/json,.json"></label><button data-action="advanced">Редактор JSON</button></div><p class="hint">Импорт заменяет черновик. Перед публикацией можно отменить изменение или восстановить предыдущую версию.</p>`)+panel('История публикаций','<p class="muted">Возвращайте предыдущую версию в черновик. Затем проверьте и опубликуйте её.</p><button data-action="history">Загрузить историю</button><div id="history-list" style="margin-top:18px"></div>');},
 security(){return panel('Сменить пароль',`<form id="password-form"><div class="fields"><label>Текущий пароль<input type="password" name="currentPassword" autocomplete="current-password" required maxlength="256"></label><label>Новый пароль<input type="password" name="newPassword" autocomplete="new-password" required minlength="12" maxlength="256"></label><label>Повторите новый пароль<input type="password" name="confirmation" autocomplete="new-password" required minlength="12" maxlength="256"></label></div><p class="hint">От 12 до 256 символов. После смены пароля все сеансы завершатся.</p><button class="primary" style="margin-top:18px">Сменить пароль</button></form>`)+panel('Ваш сеанс','<p class="muted">Вход действует 8 часов. Изменения проверяются сервером. Пароль не хранится в коде страницы.</p><button data-action="logout">Завершить сеанс</button>');}
};
async function saveDraft(){const invalid=document.querySelector('[data-invalid="true"]');if(invalid){invalid.focus();throw new Error('Исправьте формат JSON или списка чисел перед сохранением.');}if(!dirty)return;busy=true;status();try{const result=await api('api/admin/draft',{method:'PUT',data:{expectedDraftVersion:draftVersion,document:draft}});draftVersion=result.draftVersion;dirty=false;notify('Черновик сохранён.');}finally{busy=false;status();}}
function modal(title,body,buttons=[],preview=false){$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-actions').replaceChildren();$('modal').classList.toggle('preview-dialog',preview);for(const b of buttons){const el=document.createElement('button');el.textContent=b.label;el.className=b.className||'';el.addEventListener('click',async()=>{el.disabled=true;try{await b.run();}catch(e){notify(e.message,true);}finally{el.disabled=false;}});$('modal-actions').append(el);}if(!$('modal').open)$('modal').showModal();}
function confirmAction(title,body,run,label='Продолжить'){modal(title,`<p>${esc(body)}</p>`,[{label:'Отмена',run:()=> $('modal').close()},{label,className:'primary',run:async()=>{await run();$('modal').close();}}]);}
async function upload(file){if(file.size>40*1024*1024)throw new Error('Размер файла превышает 40 МБ.');return api('api/admin/upload',{method:'POST',raw:file});}
async function uploadGallery(files){const progress=$('upload-progress');let completed=0,failed=0;for(const file of files){if(progress)progress.textContent=`Загружаем ${completed+failed+1} / ${files.length}: ${file.name}`;try{const item=await upload(file);commit(()=>draft.gallery.items.unshift({...item,name:file.name,uploadedAt:new Date().toISOString()}),false);completed++;}catch(e){failed++;notify(`${file.name}: ${e.message}`,true);}}render();notify(`Добавлено в черновик: ${completed}${failed?`. Ошибок: ${failed}`:''}.`,!!failed);}
function editCard(id){const current=draft.config.cards.find(c=>c.id===id);if(!current&&!draft.config.cols.length){notify('Сначала создайте коллекцию.',true);return;}modalDraft=clone(current?{photo:{zoom:1,x:0,y:0},frame:'',frameEnabled:true,...current}:{photo:{zoom:1,x:0,y:0},frame:'',frameEnabled:true,id:nextCardId(draft.config,publishedDocument?.config),col:cardCol!=='all'?cardCol:draft.config.cols[0].id,r:'N',name:'Новая карта',img:'',enabled:true,weight:1});modal(current?'Редактировать карту':'Новая карта',`<div class="fields">${field('@.name','Название')}${field('@.col','Коллекция',{type:'select',values:draft.config.cols.map(x=>[x.id,x.name])})}${field('@.r','Редкость',{type:'select',values:['N','R','SR']})}${number('@.weight','Вес внутри редкости','1 — обычный шанс; 2 — вдвое чаще.',1000000,.1,.001)}${field('@.enabled','Показывать карту в игре',{type:'checkbox',wide:true})}</div><div style="margin-top:20px">${art('@.img','Изображение карты')}${photoControls()}${frameField('@.frame','Индивидуальная рамка','Пусто — рамка редкости из раздела «Оформление». Своя рамка заменяет общую.')}<div class="fields">${field('@.frameEnabled','Накладывать рамку на эту карту',{type:'checkbox',wide:true})}</div></div><p class="hint">Постоянный ID: ${modalDraft.id}.</p>`,[{label:'Отмена',run:()=>$('modal').close()},{label:'Сохранить карту',className:'primary',run:()=>{if(!modalDraft.name.trim()||!modalDraft.img)throw new Error('Заполните название и изображение карты.');commit(()=>{if(current)draft.config.cards[draft.config.cards.findIndex(x=>x.id===id)]=clone(modalDraft);else draft.config.cards.push(clone(modalDraft));});$('modal').close();}}]);}
function download(){const blob=new Blob([JSON.stringify({format:'yumiliya-studio-v1',document:draft},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`yumiliya-draft-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function previewAppearance(kind){
 await saveDraft();
 const website=kind==='site';
 modal(website?'Предпросмотр сайта · черновик':'Предпросмотр экрана входа · черновик',`<iframe class="preview-frame" title="${website?'Предпросмотр сайта':'Предпросмотр экрана входа'}" src="${website?'index.html?preview=1':'admin.html?login-preview=1'}"></iframe>`,[
 {label:'Телефон',run:()=>{$('modal-body').querySelector('iframe').style.cssText='width:min(390px,100%);margin:0 auto;';}},
 {label:'Полная ширина',run:()=>{$('modal-body').querySelector('iframe').style.cssText='width:100%;';}}
 ],true);
}
const actions={
 'refresh-local-balance'(){render();},
 'save-local-balance'(){const input=$('local-balance'),gems=Number(input.value);if(!input.value.trim()||!Number.isSafeInteger(gems)||gems<0)throw new Error('Введите целый баланс от 0 до 9007199254740991.');const player=localPlayer();player.gems=gems;localStorage.setItem('gacha3',JSON.stringify(player));localStorage.setItem('yumiliya-local-balance',JSON.stringify({gems,nonce:Date.now()+Math.random()}));notify('Локальный баланс обновлён: '+gems+' 💎. Публикация не требуется.');},
 async 'download-recovery'(){const copy=await api('api/admin/recovery');const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='yumiliya-draft-before-sync.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
 'restore-published-card'(button){const card=publishedDocument?.config.cards.find(item=>item.id===Number(button.dataset.id));if(!card||draft.config.cards.some(item=>item.id===card.id))return;commit(()=>{if(!draft.config.cols.some(col=>col.id===card.col))draft.config.cols.push(clone(publishedDocument.config.cols.find(col=>col.id===card.col)));draft.config.cards.push(clone(card));});},
 'reset-photo'(){modalDraft.photo={zoom:1,x:0,y:0};refreshFramePreviews();},
 'choose-frame'(b){const path=b.dataset.path,src=FRAME_PRESETS[b.dataset.preset].src;if(path.startsWith('@.')){set(path,src);modalDraft.frameEnabled=true;const toggle=$('modal-body').querySelector('[data-bind="@.frameEnabled"]');if(toggle)toggle.checked=true;}else commit(()=>set(path,src),false);const el=b.closest('.frame-field');el.querySelector('input[data-bind]').value=src;el.querySelector('.art-field>img').src=src;refreshFramePreviews();},
 'reload-published'(){confirmAction('Загрузить опубликованную версию?','Черновик и неопубликованные загрузки этого браузера будут заменены. Сначала экспортируйте нужные изменения.',async()=>{await api('api/admin/reload',{method:'POST'});await load();},'Загрузить');},
 'preview-site'(){return previewAppearance('site');},
 'preview-login'(){return previewAppearance('login');},
 'reset-site'(){confirmAction('Вернуть исходное оформление сайта?','Тексты, цвета и макет сайта в черновике вернутся к исходным. Архив и игра сохранятся.',()=>commit(()=>draft.appearance.site=clone(DEFAULT_APPEARANCE.site)),'Вернуть');},
 'reset-login'(){confirmAction('Вернуть исходный экран входа?','Оформление входа в черновике вернётся к исходному. Пароль останется прежним.',()=>commit(()=>draft.appearance.login=clone(DEFAULT_APPEARANCE.login)),'Вернуть');},

 'add-collection'(){const id='collection_'+Date.now().toString(36);commit(()=>{draft.config.cols.push({id,name:'Новая коллекция',desc:'',cover:'',enabled:false,settings:clone(draft.config.defaults)});selectedCollection=draft.config.cols.length-1;});},
 'edit-collection'(b){selectedCollection=Number(b.dataset.index);render();$('content').lastElementChild.scrollIntoView({behavior:'smooth',block:'start'});},
 'duplicate-collection'(b){const col=draft.config.cols[Number(b.dataset.index)];commit(()=>{const copy=clone(col);copy.id='collection_'+Date.now().toString(36);copy.name+=' — копия';copy.enabled=false;copy.settings.banner=0;let next=nextCardId(draft.config,publishedDocument?.config)-1;draft.config.cards.push(...draft.config.cards.filter(x=>x.col===col.id).map(x=>({...clone(x),id:++next,col:copy.id})));draft.config.cols.push(copy);selectedCollection=draft.config.cols.length-1;});},
 'remove-collection'(b){const i=Number(b.dataset.index),col=draft.config.cols[i],count=draft.config.cards.filter(x=>x.col===col.id).length;confirmAction('Удалить коллекцию?',`«${col.name}» и ${count} карт будут убраны из черновика. Отмена изменения вернёт их.`,()=>commit(()=>{draft.config.cards=draft.config.cards.filter(x=>x.col!==col.id);draft.config.cols.splice(i,1);selectedCollection=null;}),'Удалить из черновика');},
 'up-collection'(b){move(draft.config.cols,Number(b.dataset.index),-1);selectedCollection=null;},'down-collection'(b){move(draft.config.cols,Number(b.dataset.index),1);selectedCollection=null;},
 'add-card'(){editCard();},'edit-card'(b){editCard(Number(b.dataset.id));},
 'duplicate-card'(b){const card=draft.config.cards.find(x=>x.id===Number(b.dataset.id));commit(()=>draft.config.cards.push({...clone(card),id:nextCardId(draft.config,publishedDocument?.config),name:card.name+' — копия'}));},
 'remove-card'(b){const id=Number(b.dataset.id),card=draft.config.cards.find(x=>x.id===id);confirmAction('Удалить карту?',`«${card.name}» будет убрана из черновика.`,()=>commit(()=>{draft.config.cards=draft.config.cards.filter(x=>x.id!==id);for(const col of draft.config.cols)if(col.settings.banner===id)col.settings.banner=0;}),'Удалить из черновика');},
 'add-prize'(){commit(()=>draft.config.mini.prizes.push([10,1]));},'remove-prize'(b){commit(()=>draft.config.mini.prizes.splice(Number(b.dataset.index),1));},
 'add-help'(){commit(()=>draft.config.help.push({title:'Новый раздел',body:''}));},'remove-help'(b){commit(()=>draft.config.help.splice(Number(b.dataset.index),1));},'up-help'(b){move(draft.config.help,Number(b.dataset.index),-1);},'down-help'(b){move(draft.config.help,Number(b.dataset.index),1);},
 'apply-defaults'(){confirmAction('Обновить все коллекции?','Цена, шансы и гаранты во всех коллекциях будут заменены базовыми значениями. Баннер сбросится на выбор игрока.',()=>commit(()=>draft.config.cols.forEach(x=>x.settings={...clone(draft.config.defaults),banner:0})),'Применить');},
 'clear-art'(b){const path=b.dataset.path;if(path.startsWith('@.')){set(path,'');const art=b.closest('.art-field');art.querySelector('input[data-bind]').value='';art.querySelector('img').removeAttribute('src');refreshFramePreviews();}else commit(()=>set(path,''));},
 'select-all'(){for(const item of galleryItems().filter(x=>(galleryFilter==='all'||mediaType(x)===galleryFilter)&&`${x.name||''} ${x.url}`.toLowerCase().includes(galleryQuery.toLowerCase())))selectedMedia.add(item.url);render();},'clear-selection'(){selectedMedia.clear();render();},
 'remove-selected'(){confirmAction('Убрать выбранные файлы?',`Файлов: ${selectedMedia.size}. Оригиналы сохранятся. Изменение появится на сайте после публикации.`,()=>commit(()=>{draft.gallery.deleted=[...new Set([...draft.gallery.deleted,...selectedMedia])];draft.gallery.items=draft.gallery.items.filter(x=>!selectedMedia.has(x.url));selectedMedia.clear();}),'Убрать из архива');},
 'rename-media'(b){const item=galleryItems().find(x=>x.url===b.dataset.url);modal('Название файла',`<label>Название<input id="media-name" value="${esc(item.name||'')}" maxlength="300"></label>`,[{label:'Сохранить',className:'primary',run:()=>{const name=$('media-name').value;commit(()=>{const known=draft.gallery.items.find(x=>x.url===item.url);if(known)known.name=name;else draft.gallery.items.push({...item,type:mediaType(item),name});});$('modal').close();}}]);},
 'move-media'(b){const item=galleryItems().find(x=>x.url===b.dataset.url);commit(()=>{draft.gallery.items=draft.gallery.items.filter(x=>x.url!==item.url);draft.gallery.items.unshift({...item,type:mediaType(item)});});},
 'reload-gallery'(){legacyLoading=true;render();loadLegacy();},'export':download,
 'advanced'(){modal('Все настройки JSON','<p class="hint">Полная структура черновика. Изменения проверяются сервером при сохранении.</p><textarea id="advanced-json" class="code" spellcheck="false"></textarea>',[{label:'Отмена',run:()=>$('modal').close()},{label:'Применить в черновик',className:'primary',run:()=>{const doc=JSON.parse($('advanced-json').value);if(!doc.config||!doc.gallery)throw new Error('Нужны разделы config и gallery.');commit(()=>draft=doc);$('modal').close();}}]);$('advanced-json').value=JSON.stringify(draft,null,2);},
 async history(){const list=await api('api/admin/history');$('history-list').innerHTML=list.length?`<table><thead><tr><th>Версия</th><th>Дата</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>№ ${x.revision}</td><td>${x.updatedAt?esc(new Date(x.updatedAt).toLocaleString('ru-RU')):'Исходная версия'}</td><td><button data-action="restore" data-revision="${x.revision}">В черновик</button></td></tr>`).join('')}</tbody></table>`:'<p class="muted">История появится после первой публикации.</p>';},
 restore(b){confirmAction('Восстановить версию?',`Версия №${b.dataset.revision} заменит текущий черновик. Публичный сайт обновится после публикации.`,async()=>{const h=await api('api/admin/history/'+b.dataset.revision);commit(()=>draft=clone(h.document));notify('Версия восстановлена в черновик.');},'Восстановить');},
 logout(){logout();}
};
function move(list,i,delta){if(i+delta<0||i+delta>=list.length)return;commit(()=>{[list[i],list[i+delta]]=[list[i+delta],list[i]];});}
async function logout(){if(dirty){confirmAction('Выйти с несохранёнными изменениями?','Сначала сохраните или экспортируйте черновик. При выходе несохранённые изменения будут потеряны.',async()=>{await api('api/logout',{method:'POST'});dirty=false;showLogin();},'Выйти без сохранения');return;}await api('api/logout',{method:'POST'});showLogin();}
$('login-form').addEventListener('submit',async e=>{e.preventDefault();if(loginPreview)return;$('login-btn').disabled=true;$('login-error').textContent='';try{const password=$('password').value;await api('api/login',{method:'POST',data:{password}});$('password').value='';await load();}catch(e){$('login-error').textContent=e.status===401?loginAppearance.invalidPasswordMessage:e.message;$('password').value='';}finally{$('login-btn').disabled=false;}});
$('navigation').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;render();syncStudio();}});
$('content').addEventListener('click',async e=>{const go=e.target.closest('[data-go]');if(go){view=go.dataset.go;render();return;}const b=e.target.closest('[data-action]');if(b&&actions[b.dataset.action]){try{await actions[b.dataset.action](b);}catch(e){notify(e.message,true);}}const filter=e.target.closest('[data-gallery-filter]');if(filter){galleryFilter=filter.dataset.galleryFilter;selectedMedia.clear();render();}});
$('modal-body').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b&&actions[b.dataset.action])try{await actions[b.dataset.action](b);}catch(e){notify(e.message,true);}});
document.addEventListener('input',e=>{
 const input=e.target,path=input.dataset.bind;
 if(!path||input.type==='checkbox'||input.tagName==='SELECT')return;
 let value=['number','range'].includes(input.type)?Number(input.value):input.value;
 if(input.dataset.format){try{value=input.dataset.format==='json'?JSON.parse(input.value):input.value.split(/[,\s]+/).filter(Boolean).map(Number);if(input.dataset.format==='list'&&(!value.length||value.some(x=>!Number.isFinite(x))))throw new Error();delete input.dataset.invalid;input.removeAttribute('aria-invalid');}catch{input.dataset.invalid='true';input.setAttribute('aria-invalid','true');dirty=true;status();return;}}

 if(input.type==='number'&&(input.value===''||!Number.isFinite(value)))return;
 if(JSON.stringify(value)===JSON.stringify(get(path)))return;
 const apply=()=>{const old=get(path);set(path,value);if(/^config\.cols\.\d+\.id$/.test(path))for(const card of draft.config.cards)if(card.col===old)card.col=value;};
 if(path.startsWith('@.'))apply();else commit(apply,false);scheduleFramePreviews();
 document.querySelectorAll('[data-remainder]').forEach(el=>{const settings=get(el.dataset.remainder);el.textContent='Шанс N: '+(100-settings.sr-settings.r-settings.money).toFixed(1)+'%';});
});
document.addEventListener('change',async e=>{const input=e.target,path=input.dataset.bind;try{
 if(path){if(input.dataset.invalid)return;let value=input.type==='checkbox'?input.checked:['number','range'].includes(input.type)?Number(input.value):input.value;if(input.dataset.format==='json')value=JSON.parse(input.value);if(input.dataset.format==='list'){value=input.value.split(/[,\s]+/).filter(Boolean).map(Number);if(!value.length||value.some(x=>!Number.isFinite(x)))throw new Error('Укажите числа через запятую.');}if(input.tagName==='SELECT'&&path.endsWith('.banner'))value=Number(value);if(JSON.stringify(value)===JSON.stringify(get(path)))return;if(path.startsWith('@.'))set(path,value);else{const old=get(path);commit(()=>{set(path,value);if(/^config\.cols\.\d+\.id$/.test(path))for(const card of draft.config.cards)if(card.col===old)card.col=value;},false);}document.querySelectorAll('[data-remainder]').forEach(el=>{const s=get(el.dataset.remainder);el.textContent='Шанс N: '+(100-s.sr-s.r-s.money).toFixed(1)+'%';});scheduleFramePreviews();return;}
 if(input.dataset.uploadPath){input.disabled=true;try{const result=await upload(input.files[0]);if(result.type==='video')throw new Error('Для этого поля выберите изображение.');const p=input.dataset.uploadPath;if(p.startsWith('@.'))set(p,result.url);else commit(()=>set(p,result.url),false);const art=input.closest('.art-field');art.querySelector('input[data-bind]').value=result.url;art.querySelector('img').src=result.url;scheduleFramePreviews();notify('Изображение добавлено в черновик.');}finally{input.disabled=false;input.value='';}return;}
 if(input.id==='gallery-upload'){await uploadGallery([...input.files]);return;}
 if(input.dataset.mediaSelect){if(input.checked)selectedMedia.add(input.dataset.mediaSelect);else selectedMedia.delete(input.dataset.mediaSelect);render();return;}
 if(input.id==='card-col'){cardCol=input.value;render();}if(input.id==='card-rarity'){cardRarity=input.value;render();}
 if(input.id==='import-json'){const raw=JSON.parse(await input.files[0].text()),doc=raw.document||raw;if(!doc.config||!doc.gallery)throw new Error('Выберите резервную копию Юмилия Studio.');confirmAction('Импортировать копию?','Текущий черновик будет заменён. Изменение можно отменить.',()=>commit(()=>draft=doc),'Импортировать');}
 }catch(e){notify(e.message,true);if(path)input.value=input.dataset.format==='json'?JSON.stringify(get(path),null,2):get(path);}});
$('content').addEventListener('input',e=>{if(['card-search','gallery-search'].includes(e.target.id)){const input=e.target,pos=input.selectionStart,id=input.id;if(id==='card-search')cardQuery=input.value;else galleryQuery=input.value;render();$(id).focus();$(id).setSelectionRange(pos,pos);}});
$('content').addEventListener('dragover',e=>{const zone=e.target.closest('#gallery-drop');if(zone){e.preventDefault();zone.classList.add('dragging');}});$('content').addEventListener('dragleave',e=>e.target.closest('#gallery-drop')?.classList.remove('dragging'));$('content').addEventListener('drop',async e=>{const zone=e.target.closest('#gallery-drop');if(zone){e.preventDefault();zone.classList.remove('dragging');await uploadGallery([...e.dataTransfer.files]);}});
$('content').addEventListener('submit',async e=>{if(e.target.id!=='password-form')return;e.preventDefault();const data=new FormData(e.target);if(data.get('newPassword')!==data.get('confirmation'))return notify('Новые пароли не совпадают.',true);if(dirty)return notify('Сохраните черновик перед сменой пароля.',true);try{await api('api/admin/password',{method:'POST',data:{currentPassword:data.get('currentPassword'),newPassword:data.get('newPassword')}});e.target.reset();showLogin();notify('Пароль изменён. Войдите снова.');}catch(e){notify(e.message,true);}});
$('save-draft').addEventListener('click',()=>saveDraft().catch(e=>notify(e.message,true)));
$('publish').addEventListener('click',()=>confirmAction('Опубликовать изменения?','Настройки игры и архив станут доступны всем посетителям. Версия сохранится в истории.',async()=>{await saveDraft();busy=true;status();try{const result=await api('api/admin/publish',{method:'POST',data:{expectedRevision:revision,expectedDraftVersion:draftVersion}});revision=result.revision;updatedAt=result.updatedAt;publishedDocument=clone(draft);syncNotice='';try{localStorage.setItem('yumiliya-publication',JSON.stringify({revision,publishedAt:Date.now()}));}catch{}loginAppearance=clone(draft.appearance.login);notify(isPages()?'Изменения опубликованы. Сайт обновится через несколько минут.':'Готово! Сайт обновлён.');await load();}finally{busy=false;status();}},'Опубликовать'));
$('preview').addEventListener('click',async()=>{try{await saveDraft();modal('Предпросмотр · отдельное сохранение','<iframe class="preview-frame" title="Предпросмотр гачи" src="gacha_game.html?preview=1"></iframe>',[{label:'Сбросить тестовый прогресс',run:()=>{$('modal-body').querySelector('iframe').src='gacha_game.html?preview=1&reset=1&t='+Date.now();}}],true);}catch(e){notify(e.message,true);}});
$('undo').addEventListener('click',()=>{if(!undo.length)return;redo.push(clone(draft));draft=undo.pop();dirty=true;render();});$('redo').addEventListener('click',()=>{if(!redo.length)return;undo.push(clone(draft));draft=redo.pop();dirty=true;render();});
window.addEventListener('focus',syncStudio);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncStudio();});
$('logout').addEventListener('click',()=>logout().catch(e=>notify(e.message,true)));$('modal-x').addEventListener('click',()=>$('modal').close());$('modal').addEventListener('close',()=>{$('modal-body').replaceChildren();modalDraft=null;});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
$('server-note').hidden=location.protocol!=='file:';
$('login-btn').disabled=true;
async function initializeStudio(){
 try{loginAppearance=(await loadAppearance(loginPreview)).login;}catch(error){if(loginPreview){showLogin();$('login-error').textContent=error.message;return;}}
 applyLoginAppearance(loginAppearance);configurePasswordLogin();
 if(loginPreview){showLogin();$('password').disabled=true;$('login-btn').disabled=true;return;}
 if(location.protocol==='file:')return;
 $('login-btn').disabled=false;
 await load().catch(error=>{showLogin();if(error.status!==401)$('login-error').textContent=error.message;});
}
function configurePasswordLogin(){
 if(isPages())$('server-note').hidden=true;
}
if(isPages())providePreview(()=>draft,source=>source===$('modal-body').querySelector('iframe')?.contentWindow);
initializeStudio();
